#!/usr/bin/env bash
set -euo pipefail
MAS_ROOT=${MAS_ROOT:-/path/to/MAS_Loop}
JOB_ENV=${JOB_ENV:-/path/to/checkpoints/benchmarks/current_mas_loop_job.env}
TS=$(date '+%F_%T_%Z')
echo "========== MAS-Loop 30min check ${TS} =========="
if [[ ! -s "${JOB_ENV}" ]]; then
  echo "monitor_health=NO_CURRENT_JOB_FILE path=${JOB_ENV}"
  exit 0
fi
# This file is generated by MAS_Loop launchers and contains simple KEY=value rows.
# shellcheck disable=SC1090
source "${JOB_ENV}"
: "${SESSION:?missing SESSION}" "${RUN_DIR:?missing RUN_DIR}"
DATASET=${DATASET:-unknown}
EXPECTED_SAMPLES=${EXPECTED_SAMPLES:-0}
PAIR_GROUP_SIZE=${PAIR_GROUP_SIZE:-${LOOP_ROUNDS:-8}}
export SESSION RUN_DIR DATASET EXPECTED_SAMPLES PAIR_GROUP_SIZE MAS_ROOT
export CHECKPOINT_ROOT=${CHECKPOINT_ROOT:-}
export MODE=${MODE:-training}
export WAIT_LOG=${WAIT_LOG:-}
export VLLM_SLEEP_STATE=${VLLM_SLEEP_STATE:-}
export VLLM_SLEEP_EVENTS=${VLLM_SLEEP_EVENTS:-}
printf 'session=%s\nrun_dir=%s\ndataset=%s expected_samples=%s pair_group_size=%s\n' \
  "$SESSION" "$RUN_DIR" "$DATASET" "$EXPECTED_SAMPLES" "$PAIR_GROUP_SIZE"
if tmux has-session -t "$SESSION" 2>/dev/null; then TMUX_ALIVE=1; else TMUX_ALIVE=0; fi
echo "tmux_alive=${TMUX_ALIVE}"
echo "-- gpustat GPUs 8-15 --"
gpustat --no-color -p 2>/dev/null | awk 'NR==1 || /^\[(8|9|10|11|12|13|14|15)\]/' || true
python3 - <<'PY'
import json, os, pathlib, re, subprocess, time, datetime
root=pathlib.Path(os.environ['RUN_DIR']); session=os.environ['SESSION']
expected_samples=int(os.environ.get('EXPECTED_SAMPLES','0')); group_size=int(os.environ.get('PAIR_GROUP_SIZE','8'))
expected=expected_samples*group_size if expected_samples else None

def read_tail(p, n=8*1024*1024):
    try:
        with p.open('rb') as f:
            f.seek(0,2); size=f.tell(); f.seek(max(0,size-n)); return f.read().decode(errors='ignore')
    except Exception: return ''

def count_jsonl(p):
    total=bad=errors=0; keys=set(); stages={}
    if not p.exists(): return {'path':str(p),'count':0,'bad_json':0,'record_errors':0,'unique_sample_stage':0,'stage_histogram':{}}
    with p.open(errors='ignore') as f:
        for line in f:
            if not line.strip(): continue
            total+=1
            try: row=json.loads(line)
            except Exception: bad+=1; continue
            stage=row.get('rollout_sample_index', row.get('inner_loop_round')); sample=row.get('dataset_sample_id')
            if sample is None: sample=row.get('grpo_group_uid') or row.get('loop_id')
            keys.add((str(sample),stage)); stages[str(stage)]=stages.get(str(stage),0)+1
            errs=row.get('errors') or row.get('violations') or []
            err_field=row.get('error')
            if err_field or errs: errors+=1
    return {'path':str(p),'count':total,'bad_json':bad,'record_errors':errors,'unique_sample_stage':len(keys),'stage_histogram':stages,
            'last_write_age_s':round(time.time()-p.stat().st_mtime,1)}

def count_jsonl_paths(paths, role):
    aggregate={'path':','.join(str(p) for p in paths),'shards':len(paths),'count':0,'bad_json':0,
               'record_errors':0,'unique_sample_stage':0,'stage_histogram':{}}
    unique=set(); newest=None
    for p in paths:
        part=count_jsonl(p)
        aggregate['count']+=part['count']; aggregate['bad_json']+=part['bad_json']
        aggregate['record_errors']+=part['record_errors']
        for stage,count in part['stage_histogram'].items():
            aggregate['stage_histogram'][stage]=aggregate['stage_histogram'].get(stage,0)+count
        if p.exists(): newest=max(newest or 0,p.stat().st_mtime)
        with p.open(errors='ignore') as handle:
            for line in handle:
                try: row=json.loads(line)
                except Exception: continue
                if row.get('role') != role: continue
                stage=row.get('rollout_sample_index',row.get('inner_loop_round'))
                sample=row.get('dataset_sample_id') or row.get('grpo_group_uid') or row.get('loop_id')
                unique.add((str(sample),stage))
    aggregate['unique_sample_stage']=len(unique)
    if newest is not None: aggregate['last_write_age_s']=round(time.time()-newest,1)
    return aggregate

# One Orchestra canonical row is the complete O_k -> E_k pair. It proves both
# role samples were retained without requiring duplicate 70-90 MB JSONL files.
canonical_orchestra=sorted(root.glob('round_*/orchestra/rollouts/canonical_rollouts/*.jsonl'))
if canonical_orchestra:
    canonical=count_jsonl_paths(canonical_orchestra,'orchestra')
    pairs={'orchestra':dict(canonical), 'editor':dict(canonical)}
    pairs['editor']['path']=canonical['path']+' (structured_pair.editor)'
else:
    # Backward-compatible reporting for pre-sharding runs.
    pairs={}
    for role in ('orchestra','editor'):
        candidates=[root/'rollouts'/'pairs'/f'{role}_loop_stage_pairs.jsonl', root/'rollouts'/'pairs'/f'{role}_rollout_pairs.jsonl']
        p=next((x for x in candidates if x.exists()), candidates[0])
        pairs[role]=count_jsonl(p)

train_log_path=root/'logs'/'full_train.log'
wait_log_path=pathlib.Path(os.environ['WAIT_LOG']) if os.environ.get('WAIT_LOG') else None
wait_log=read_tail(wait_log_path, n=1024*1024) if wait_log_path else ''
sources=[read_tail(train_log_path)]
cap=subprocess.run(['tmux','capture-pane','-p','-t',session,'-S','-5000'],text=True,capture_output=True)
tmux_alive=cap.returncode==0
if cap.stdout: sources.append(cap.stdout)
log='\n'.join(sources)
steps=[int(x) for x in re.findall(r'training/global_step:(\d+)',log)]
progress=re.findall(r'Training Progress:\s*.*?(\d+)/(\d+)',log)
metrics_global_step=steps[-1] if steps else None
progress_completed=int(progress[-1][0]) if progress else None
progress_total=int(progress[-1][1]) if progress else None
# tqdm updates can be visible before the large metrics line is flushed.  Report both
# sources and expose a conservative effective completed-step value instead of making
# a healthy next rollout look as if the previous PPO update never completed.
completed_candidates=[x for x in (metrics_global_step,progress_completed) if x is not None]
effective_completed_steps=max(completed_candidates) if completed_candidates else None
train_log_age_s=(time.time()-train_log_path.stat().st_mtime) if train_log_path.exists() else None
err_patterns=['Traceback','EngineDeadError','OutOfMemoryError','CUDA out of memory','CUDA Error: out of memory','TimeoutError','RPC call to execute_model timed out','Connection refused','Address already in use','NCCL watchdog','output/group mismatch']
errs={x:log.count(x) for x in err_patterns if x in log}
exit_status=(root/'exit.status').read_text(errors='ignore').strip() if (root/'exit.status').exists() else None
checkpoint_root=pathlib.Path(os.environ['CHECKPOINT_ROOT']) if os.environ.get('CHECKPOINT_ROOT') else None
local_checkpoints=[]
if checkpoint_root and checkpoint_root.exists():
    for config in sorted(checkpoint_root.glob('round_*/**/global_step_*/actor/huggingface/config.json')):
        hf_dir=config.parent
        if any(hf_dir.glob('*.safetensors')):
            role='orchestra' if 'orchestra' in config.parts else ('editor' if 'editor' in config.parts else 'unknown')
            match=re.search(r'global_step_(\d+)',str(config))
            local_checkpoints.append({'role':role,'step':int(match.group(1)) if match else None,'path':str(hf_dir)})
counts=[pairs[r]['count'] for r in ('orchestra','editor')]
waiting_for_isolation=(
    os.environ.get('MODE') == 'concurrency_trial'
    and '[trial] waiting for exclusive access' in wait_log
    and '[gpu-isolation] READY' not in wait_log
)
if exit_status and 'EXIT_CODE=0' in exit_status:
    health='COMPLETED_OK'
elif waiting_for_isolation and tmux_alive:
    health='WAITING_FOR_GPU_ISOLATION'
elif not tmux_alive:
    health='FAILED_PROCESS_EXITED'
elif errs:
    health='ERROR_SIGNATURE_FOUND'
elif (train_log_age_s is not None and train_log_age_s < 900) or any(
        c>0 and pairs[r].get('last_write_age_s',999999)<900
        for c,r in zip(counts,('orchestra','editor'))):
    health='ACTIVE_PROGRESS'
else:
    age=time.time()-float(os.environ.get('START_TIME',time.time())) if os.environ.get('START_TIME') else 0
    health='STARTING_UP' if age<900 else 'POSSIBLE_STALL_NO_PROGRESS_15MIN'
sleep_state={}
state_candidates=[]
if os.environ.get('VLLM_SLEEP_STATE'):
    state_candidates.append(pathlib.Path(os.environ['VLLM_SLEEP_STATE']))
state_candidates.extend((root/'vllm_sleep'/'mas_loop_vllm_sleep.lock.state.json', root/'vllm_sleep'/'state.json'))
for candidate in state_candidates:
    if candidate.exists():
        try: sleep_state=json.loads(candidate.read_text()); sleep_state['path']=str(candidate)
        except Exception as exc: sleep_state={'path':str(candidate),'error':str(exc)}
        break
events=[]
event_candidates=[]
if os.environ.get('VLLM_SLEEP_EVENTS'):
    event_candidates.append(pathlib.Path(os.environ['VLLM_SLEEP_EVENTS']))
event_candidates.extend((root/'vllm_sleep'/'events.jsonl', root/'vllm_sleep'/'mas_loop_vllm_sleep.lock.state.json.events.jsonl'))
for candidate in event_candidates:
    if candidate.exists():
        for line in candidate.read_text(errors='ignore').splitlines()[-12:]:
            try: events.append(json.loads(line))
            except Exception: pass
        break

out={'time':datetime.datetime.now().isoformat(timespec='seconds'),'health':health,'tmux_alive':tmux_alive,
     'mode':os.environ.get('MODE'),'wait_log':str(wait_log_path) if wait_log_path else None,
     'dataset':os.environ.get('DATASET'),'pair_group_size':group_size,'expected_pairs_per_role':expected,
     'vllm_exclusive_owner':sleep_state,'recent_vllm_transitions':events,
     'metrics_global_step':metrics_global_step,
     'progress_completed_steps':progress_completed,
     'progress_total_steps':progress_total,
     'effective_completed_steps':effective_completed_steps,
     'latest_progress':f'{progress_completed}/{progress_total}' if progress else None,
     'full_train_log_age_s':round(train_log_age_s,1) if train_log_age_s is not None else None,
     'pairs':pairs,'errors':errs,'exit_status':exit_status,'local_checkpoint_count':len(local_checkpoints),
     'latest_local_checkpoint':local_checkpoints[-1] if local_checkpoints else None}
print(json.dumps(out,ensure_ascii=False,indent=2))
state=root/'monitor'/'masloop_monitor_state.json'
state.parent.mkdir(parents=True, exist_ok=True)
state.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
PY
